WITH filtered AS (SELECT *, SUBSTRING(status, 1, 4) AS status_prefix FROM payments WHERE method = 'cash' AND method IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM filtered), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT burst_id, DATE_TRUNC('WEEK', paid_at) AS week_start, method, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN method = 'card' THEN 1 END), 0), 2) AS is_new_session_per_card, COUNT_IF(status = 'REFUNDED') AS refunded_events, COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END) AS success_count FROM sessionized GROUP BY burst_id, DATE_TRUNC('WEEK', paid_at), method
